 const target=e.target.closest?.('.wire-pot,.fader-box,input[type="range"]');
 if(!target)return;
 const input=target.matches?.('input[type="range"]')?target:
  target.querySelector?.('input[type="range"]');
 const allowed=new Set(['level','pan','wireGain','trim','sendLevel','sendPan']);
 if(!input||input.disabled||!allowed.has(input.dataset.field))return;
 const min=Number(input.min),max=Number(input.max),prev=Number(input.value);
 if(![min,max,prev].every(Number.isFinite))return;
 e.preventDefault();
 const pixels=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?240:1);
 const accumulated=(wheelResidue.get(input)||0)+pixels;
 const detents=Math.trunc(accumulated/100);
 wheelResidue.set(input,accumulated-detents*100);
 if(!detents)return;
 const step=e.shiftKey?(input.dataset.field==='pan'||input.dataset.field==='sendPan'?1:.1):
  (input.dataset.field==='pan'||input.dataset.field==='sendPan'?2:.5);
 const resolution=Number(input.step)||.1;
 const next=Math.round(Math.max(min,Math.min(max,prev-detents*step))/resolution)*resolution;
 if(next===prev)return;
 input.value=String(next);
 if(input.dataset.field==='pan')input.dataset.panKeyboard='true';
 handleField({target:input,type:'input',altKey:e.altKey});
},{passive:false});
